"""Interactive chat interface for RAG"""
from .config import OPENAI_API_KEY
from .vectorstore.chroma_client import ChromaClient
from .retrieval.query_engine import QueryEngine


def main():
    """Start interactive chat session"""
    if not OPENAI_API_KEY:
        print("Error: OPENAI_API_KEY not set")
        return

    print("RAG Document Q&A Chat")
    print("Type 'quit' or 'exit' to end the session\n")

    chroma = ChromaClient()
    engine = QueryEngine(chroma)

    while True:
        try:
            query = input("You: ").strip()
            if query.lower() in ["quit", "exit", "q"]:
                print("Goodbye!")
                break
            if not query:
                continue

            result = engine.query(query)
            print(f"\nAssistant: {result['answer']}\n")
            if result.get("sources"):
                print("Sources:")
                for source in result["sources"]:
                    print(f"  - {source}")
                print()

        except KeyboardInterrupt:
            print("\nGoodbye!")
            break
        except Exception as e:
            print(f"Error: {e}\n")


if __name__ == "__main__":
    main()

"""Query engine for RAG"""
from typing import Dict, Any, List
import json

from ..vectorstore.chroma_client import ChromaClient
from ..vectorstore.retriever import Retriever
from ..llm.openai_adapter import OpenAILLM


class QueryEngine:
    """Main query engine for RAG"""

    def __init__(self, chroma_client: ChromaClient, llm_provider: str = "openai"):
        self.retriever = Retriever(chroma_client)
        self.llm = self._get_llm(llm_provider)

    def _get_llm(self, provider: str):
        """Get LLM adapter based on provider"""
        if provider == "openai":
            return OpenAILLM()
        # Add other providers as needed
        return OpenAILLM()

    def query(self, question: str) -> Dict[str, Any]:
        """Process a query and return answer with sources"""
        # Retrieve relevant documents
        docs = self.retriever.get_relevant_docs(question, k=4)

        if not docs:
            return {
                "answer": "No relevant documents found. Please add documents to the data/documents folder and rebuild the index.",
                "sources": []
            }

        # Build context from retrieved documents
        context = "\n\n".join([doc["content"] for doc in docs])

        # Generate answer using LLM
        answer = self.llm.generate_answer(question, context)

        # Extract sources
        sources = list(set([doc["metadata"].get("source", "Unknown") for doc in docs if doc["metadata"]]))

        return {
            "answer": answer,
            "sources": sources,
            "context": context
        }

    def get_relevant_documents(self, query: str, k: int = 4) -> List[Dict[str, Any]]:
        """Get relevant documents without generating answer"""
        return self.retriever.get_relevant_docs(query, k=k)

"""ChromaDB client for vector storage"""
from typing import List, Dict, Any, Optional
import chromadb
from chromadb.config import Settings

from ..config import CHROMA_PATH, EMBEDDING_MODEL, OPENAI_API_KEY


class ChromaClient:
    """ChromaDB client wrapper"""

    def __init__(self, collection_name: str = "documents"):
        self.client = chromadb.PersistentClient(path=CHROMA_PATH)
        self.collection_name = collection_name
        self.collection = self._get_or_create_collection()

    def _get_or_create_collection(self):
        """Get or create the documents collection"""
        return self.client.get_or_create_collection(
            name=self.collection_name,
            metadata={"description": "RAG document embeddings"}
        )

    def add_documents(self, documents: List[str], metadatas: Optional[List[Dict]] = None, ids: Optional[List[str]] = None):
        """Add documents to the collection"""
        if ids is None:
            ids = [f"doc_{i}" for i in range(len(documents))]

        if metadatas is None:
            metadatas = [{} for _ in documents]

        self.collection.add(
            documents=documents,
            metadatas=metadatas,
            ids=ids
        )

    def query(self, query_text: str, n_results: int = 4) -> Dict[str, Any]:
        """Query the vector store"""
        results = self.collection.query(
            query_texts=[query_text],
            n_results=n_results
        )
        return results

    def delete_collection(self):
        """Delete the collection"""
        self.client.delete_collection(self.collection_name)

    def get_count(self) -> int:
        """Get the number of documents in the collection"""
        return self.collection.count()


def get_embedding_function():
    """Get the OpenAI embedding function"""
    try:
        from langchain_openai import OpenAIEmbeddings
    except ImportError:
        from langchain.embeddings import OpenAIEmbeddings

    return OpenAIEmbeddings(
        model=EMBEDDING_MODEL,
        api_key=OPENAI_API_KEY
    )

"""Retriever utilities"""
from typing import List, Dict, Any

from .chroma_client import ChromaClient


class Retriever:
    """Document retriever using Chroma"""

    def __init__(self, chroma_client: ChromaClient):
        self.client = chroma_client

    def get_relevant_docs(self, query: str, k: int = 4) -> List[Dict[str, Any]]:
        """Retrieve relevant documents for a query"""
        results = self.client.query(query, n_results=k)

        documents = []
        if results["documents"]:
            for i, doc in enumerate(results["documents"][0]):
                documents.append({
                    "content": doc,
                    "metadata": results["metadatas"][0][i] if results["metadatas"] else {},
                    "distance": results["distances"][0][i] if results.get("distances") else None
                })

        return documents

"""OpenAI LLM adapter"""
from typing import Optional

from ..config import OPENAI_API_KEY


class OpenAILLM:
    """OpenAI LLM wrapper for RAG"""

    def __init__(self, model: str = "gpt-4o-mini"):
        self.model = model
        self.api_key = OPENAI_API_KEY

    def generate_answer(self, question: str, context: str) -> str:
        """Generate answer using OpenAI with RAG context"""
        try:
            from openai import OpenAI
        except ImportError:
            return "Error: openai package not installed"

        client = OpenAI(api_key=self.api_key)

        prompt = f"""You are a helpful assistant answering questions based on the provided context.
If the answer is in the context, provide it. If not, say you don't have enough information.

Context:
{context}

Question: {question}

Answer:"""

        try:
            response = client.chat.completions.create(
                model=self.model,
                messages=[
                    {"role": "system", "content": "You are a helpful assistant that answers questions based on the provided context."},
                    {"role": "user", "content": prompt}
                ],
                temperature=0.7,
                max_tokens=1000
            )
            return response.choices[0].message.content
        except Exception as e:
            return f"Error generating answer: {str(e)}"

"""Document loaders for various file types"""
from pathlib import Path
from typing import List

try:
    from langchain_community.document_loaders import (
        TextLoader,
        MarkdownLoader,
        PyPDFLoader,
        UnstructuredMarkdownLoader
    )
except ImportError:
    from langchain.document_loaders import (
        TextLoader,
        MarkdownLoader,
        PyPDFLoader
    )

from langchain.schema import Document


def load_document(file_path: str) -> List[Document]:
    """Load a document from file path"""
    path = Path(file_path)
    suffix = path.suffix.lower()

    if suffix == ".pdf":
        loader = PyPDFLoader(file_path)
    elif suffix == ".md":
        loader = MarkdownLoader(file_path)
    elif suffix == ".txt":
        loader = TextLoader(file_path, encoding="utf-8")
    else:
        raise ValueError(f"Unsupported file type: {suffix}")

    return loader.load()


def load_directory(dir_path: str) -> List[Document]:
    """Load all supported documents from a directory"""
    documents = []
    path = Path(dir_path)

    for file_path in path.rglob("*"):
        if file_path.is_file() and file_path.suffix.lower() in [".txt", ".md", ".pdf"]:
            try:
                docs = load_document(str(file_path))
                documents.extend(docs)
            except Exception as e:
                print(f"Warning: Failed to load {file_path}: {e}")

    return documents

"""Text splitting utilities for document chunking"""
from typing import List

try:
    from langchain.text_splitter import RecursiveCharacterTextSplitter
except ImportError:
    from langchain.text_splitter import CharacterTextSplitter as RecursiveCharacterTextSplitter

from langchain.schema import Document


def split_documents(documents: List[Document], chunk_size: int = 1000, chunk_overlap: int = 200) -> List[Document]:
    """Split documents into chunks"""
    splitter = RecursiveCharacterTextSplitter(
        chunk_size=chunk_size,
        chunk_overlap=chunk_overlap,
        separators=["\n\n", "\n", " ", ""]
    )
    return splitter.split_documents(documents)


def split_text(text: str, chunk_size: int = 1000, chunk_overlap: int = 200) -> List[str]:
    """Split raw text into chunks"""
    splitter = RecursiveCharacterTextSplitter(
        chunk_size=chunk_size,
        chunk_overlap=chunk_overlap,
        separators=["\n\n", "\n", " ", ""]
    )
    return splitter.split_text(text)

